import Foundation
import XCTest
import RobotPlugin
import ChassisPlugin
import SimulationContracts

/// Offline example data, generated by the existing reference simulators, never by a hardware path.
final class PanelReferenceTraceTests: XCTestCase {
    struct Frame: Encodable {
        let time_s: Double
        let joints_rad: [Double]
        let speed_m_s: Double
        let steering_rad: Double
        let phase: Int
        let fault: Bool
    }
    struct Trace: Encodable {
        let schema_version = 1
        let source = "synthetic-reference-simulators"
        let robot_model: String
        let chassis_model: String
        let period_s = 4.4
        let frames: [Frame]
    }

    func testReferenceActualTraceMatchesSimulatorOutputAndHasRestingLoopBoundary() throws {
        var robot = try RobotSimulator(instanceID: "panel.synthetic.robot")
        var chassis = try ChassisSimulator(instanceID: "panel.synthetic.chassis")
        try robot.initialize(Array(repeating: 0, count: 6), generation: robot.control.generation)
        try chassis.initialize([0, 0, 0], generation: chassis.control.generation)
        let r = try robot.acquire(generation: robot.control.generation, owner: "synthetic.source", ttl: 5, controlToken: "offline.robot")
        let c = try chassis.acquire(generation: chassis.control.generation, owner: "synthetic.source", ttl: 5, controlToken: "offline.chassis")
        func rp(_ n: Int) -> DeviceCommandProof { .init(generation: r.generation, token: r.control_token, sequence: n) }
        func cp(_ n: Int) -> DeviceCommandProof { .init(generation: c.generation, token: c.control_token, sequence: n) }
        try robot.enable(rp(1)); try chassis.enable(cp(1))
        try robot.move(rp(2), target: [0.5, -0.4, 0.3, -0.2, 0.1, -0.6], duration: 1.5, validFor: 1.6)
        try chassis.drive(cp(2), speed: 0.6, steering: 0.3, validFor: 2)
        // Quantization belongs only to this display recording; it never modifies simulator actuals.
        func q(_ x: Double) -> Double { (x * 1_000_000).rounded() / 1_000_000 }
        var frames: [Frame] = []
        for tick in 0 ... 44 {
            if tick == 16 {
                try robot.move(rp(3), target: Array(repeating: 0, count: 6), duration: 1.5, validFor: 1.6)
                try chassis.drive(cp(3), speed: -0.3, steering: -0.2, validFor: 2)
            }
            if tick == 32 { try chassis.drive(cp(4), speed: 0, steering: 0, validFor: 1) }
            let ra = try XCTUnwrap(robot.snapshot().actual)
            let ca = try XCTUnwrap(chassis.snapshot().actual)
            frames.append(Frame(time_s: Double(tick) / 10, joints_rad: ra.joints_rad.map(q), speed_m_s: q(ca.speed_m_s), steering_rad: q(ca.steering_angle_rad), phase: tick == 0 || tick >= 40 ? 0 : (tick < 16 ? 1 : (tick < 32 ? 2 : 3)), fault: false))
            if tick < 44 { try robot.advance(0.1); try chassis.advance(0.1) }
        }
        let trace = Trace(robot_model: robot.model.id, chassis_model: chassis.model.id, frames: frames)
        let encoder = JSONEncoder(); encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        var data = try encoder.encode(trace); data.append(10)
        let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        let fixture = root.appendingPathComponent("clients/python/surface_panel_demo/reference_actual.json")
        if let output = ProcessInfo.processInfo.environment["SURFACE_PANEL_TRACE_OUTPUT"] {
            try data.write(to: URL(fileURLWithPath: output))
        }
        XCTAssertEqual(try Data(contentsOf: fixture), data)
        XCTAssertEqual(frames.first!.joints_rad, frames.last!.joints_rad)
        XCTAssertEqual(frames.first!.speed_m_s, 0); XCTAssertEqual(frames.last!.speed_m_s, 0)
        XCTAssertEqual(frames.first!.steering_rad, 0); XCTAssertEqual(frames.last!.steering_rad, 0)
        XCTAssertEqual(frames.last!.phase, 0)
        XCTAssertTrue(frames.contains { abs($0.speed_m_s) > 0 })
        XCTAssertTrue(frames.contains { abs($0.steering_rad) > 0 })
        for index in 0 ..< 6 { XCTAssertTrue(frames.contains { abs($0.joints_rad[index]) > 0 }) }
    }
}
